package http

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// AnyValue is a placeholder for an expected JSON body that matches any value,
// e.g. timestamps generated by the service. The field itself must be present.
const AnyValue = "{{any}}"

// anyValuePointers returns JSON pointers to the AnyValue placeholders of expected
// and checks that each of them is present in actual.
func anyValuePointers(expected, actual []byte) ([]string, error) {
	var expectedDoc, actualDoc any

	if err := json.Unmarshal(expected, &expectedDoc); err != nil {
		return nil, fmt.Errorf("decode expected body: %w", err)
	}

	if err := json.Unmarshal(actual, &actualDoc); err != nil {
		return nil, fmt.Errorf("decode actual body: %w", err)
	}

	var pointers []string
	collectAnyValuePointers(expectedDoc, "", &pointers)

	for _, pointer := range pointers {
		if !hasPointer(actualDoc, pointer) {
			return nil, fmt.Errorf("response body has no value at %q: %s", pointer, actual)
		}
	}

	return pointers, nil
}

func collectAnyValuePointers(doc any, pointer string, pointers *[]string) {
	switch v := doc.(type) {
	case string:
		if v == AnyValue {
			*pointers = append(*pointers, pointer)
		}
	case map[string]any:
		for key, value := range v {
			collectAnyValuePointers(value, pointer+"/"+escapePointerToken(key), pointers)
		}
	case []any:
		for i, value := range v {
			collectAnyValuePointers(value, pointer+"/"+strconv.Itoa(i), pointers)
		}
	}
}

func hasPointer(doc any, pointer string) bool {
	if pointer == "" {
		return true
	}

	for _, token := range strings.Split(pointer[1:], "/") {
		token = unescapePointerToken(token)

		switch v := doc.(type) {
		case map[string]any:
			value, ok := v[token]
			if !ok {
				return false
			}
			doc = value
		case []any:
			i, err := strconv.Atoi(token)
			if err != nil || i < 0 || i >= len(v) {
				return false
			}
			doc = v[i]
		default:
			return false
		}
	}

	return true
}

// see RFC 6901, section 4
func escapePointerToken(token string) string {
	return strings.ReplaceAll(strings.ReplaceAll(token, "~", "~0"), "/", "~1")
}

func unescapePointerToken(token string) string {
	return strings.ReplaceAll(strings.ReplaceAll(token, "~1", "/"), "~0", "~")
}
